    def refresh_ports(self):
        """刷新可用串口列表"""
        # 如果串口已打开，不刷新端口列表
        if self.serial_opened:
            QMessageBox.information(self, "提示", "串口打开时无法刷新端口列表")
            return
        
        self.port_combo.clear()
        ports = serial.tools.list_ports.comports()
        for port in ports:
            if not port.device or not port.description:
                continue
            port_item = f"{port.device} - {port.description}"
            self.port_combo.addItem(port_item)
            
            # 如果之前有打开的端口，尝试选中它
            if self.current_port and port.device == self.current_port:
                self.port_combo.setCurrentText(port_item)
        
    def toggle_serial(self):
        """打开/关闭串口"""
        if self.serial_opened:
            self.close_serial()
        else:
            self.open_serial()
    
    def open_serial(self):
        """打开串口"""
        if not self.port_combo.currentText():
            QMessageBox.warning(self, "警告", "请选择串口")
            return False
        
        self.open_serial_btn.setEnabled(False)
        try:
            # 解析端口名
            port_name = self.port_combo.currentText().split(' - ')[0]
            baudrate = int(self.baud_combo.currentText())
            
            # 保存当前配置
            self.current_port = port_name
            self.current_baudrate = str(baudrate)
            
            # 调用串口打开回调
            if self.serial_opeb_callback:
                open_result = self.serial_opeb_callback(port_name, baudrate, 4096)
                if isinstance(open_result, tuple):
                    opened, error_message = open_result
                else:
                    opened, error_message = bool(open_result), "未知错误"

                if opened:
                    self.serial_opened = True
                    self.update_serial_button_style()

                    # 禁用配置选项（串口打开时不可修改）
                    self.port_combo.setEnabled(False)
                    self.baud_combo.setEnabled(False)
                    self.refresh_btn.setEnabled(False)
                    
                    self.status_bar.showMessage('串口已连接')
                    return True
                else:
                    # 如果打开失败，恢复状态
                    self.current_port = ""
                    self.current_baudrate = ""
                    QMessageBox.critical(self, "错误", f"打开串口失败: {error_message}")
            else:
                QMessageBox.critical(self, "错误", "未配置串口打开回调")
            
        except Exception as e:
            self.current_port = ""
            self.current_baudrate = ""
            QMessageBox.critical(self, "错误", f"打开串口失败: {str(e)}")
        finally:
            self.open_serial_btn.setEnabled(True)
        
        return False
    
    def close_serial(self):
        """关闭串口"""
        self.open_serial_btn.setEnabled(False)
        try:
            if self.serial_close_callback:
                self.serial_close_callback()
        except Exception as e:
            QMessageBox.warning(self, "串口关闭异常", str(e))
        finally:
            self.set_serial_disconnected_ui('串口已断开')
            self.open_serial_btn.setEnabled(True)

    def set_serial_disconnected_ui(self, message='串口已断开'):
        """只更新断线后的界面状态，不重复调用串口关闭回调。"""
        self.serial_opened = False
        self.update_serial_button_style()
        
        # 启用配置选项（串口关闭时可修改）
        self.port_combo.setEnabled(True)
        self.baud_combo.setEnabled(True)
        self.refresh_btn.setEnabled(True)
        
        self.status_bar.showMessage(message)
    
