    def display_float(self, value):
        if value is None:
            return "None"
        if isinstance(value, float):
            if value < 0.0:
                if value < -100:
                    return f'{value:.2f}'
                elif value < -100:
                    return f'{value:.3f}'
                else:
                    return f'{value:.4f}'
            else:
                if value > 1000:
                    return f' {value:.2f}'
                elif value > 100:
                    return f' {value:.3f}'
                else:
                    return f' {value:.4f}'
        elif isinstance(value, int):
            if value < 0:
                return f'{value}'
            else:
                return f' {value}'
        else:
            return f'{value}'

    def find_closest_index(self, arr, value):
        """在有序列表中找到最接近值的索引"""
        if not arr:
            return -1
        
        if value <= arr[0]:
            return 0
        
        if value >= arr[-1]:
            return len(arr) - 1
        
        left, right = 0, len(arr) - 1
        
        while left <= right:
            mid = (left + right) // 2
            
            if arr[mid] == value:
                return mid
            elif arr[mid] < value:
                left = mid + 1
            else:
                right = mid - 1
        
        # 比较左右两个元素哪个更接近
        diff_left = abs(value - arr[left-1])
        diff_right = abs(value - arr[left])
        
        if diff_left <= diff_right:
            return left - 1
        else:
            return left

    def add_curve(self, curve_name, color=None):
        """添加新曲线"""
        if color is None:
            color = self.colors[self.color_index % len(self.colors)]
            self.color_index += 1
        
        self.curve_colors[curve_name] = color
        pen = pg.mkPen(color=color, width=2)
        
        if curve_name not in self.curves:
            self.curves[curve_name] = self.plot.plot(
                pen=pen,
                name=curve_name
            )
            self.curve_data[curve_name] = []
        else:
            print(f"曲线 {curve_name} 已经存在")

    def update_cursor_display(self):
        """更新绘图区域的鼠标位置显示。"""
        # 获取全局鼠标位置
        mouse_global = QCursor.pos()
        mouse_local = self.plot.mapFromGlobal(mouse_global)
        
        # 检查鼠标是否在绘图区域内
        if self.plot.rect().contains(mouse_local):
            # 转换为场景坐标
            mouse_scene = self.plot.plotItem.vb.mapSceneToView(mouse_local)
            x = mouse_scene.x()
            y = mouse_scene.y()
            
            # 更新十字光标位置
            self.vLine.setPos(x)
            self.hLine.setPos(y)
            
            # 显示光标位置
            show_str = f"光标位置：({x:.2f}, {y:.2f}), 角度 :{y/math.pi * 180.0:.2f}°, 速度 :{y*30.0/math.pi:.2f}rpm"
            self.display_box_1.setText(show_str)

