class CalibrationDialog(QDialog):
    def __init__(self, motor_name, parent=None, auto_mode=True, angle_check_enabled=True, skip_confirm_enabled=False):
        super().__init__(parent)
        self.parent = parent
        self.motor_name = motor_name
        self.motor_id = 126 if motor_name == "左电机" else 127
        self.auto_mode = auto_mode
        self.angle_check_enabled = angle_check_enabled
        self.skip_confirm_enabled = skip_confirm_enabled
        
        self.setWindowTitle(f"{motor_name}一键校准")
        self.setMinimumSize(620, 480)
        self.resize(760, 640)

        layout = QVBoxLayout()
        layout.setContentsMargins(14, 14, 14, 14)
        layout.setSpacing(10)

        self.status_label = QLabel(f"正在校准{motor_name}...")
        self.status_label.setFont(QFont("Microsoft YaHei UI", 14, QFont.Bold))
        self.status_label.setAlignment(Qt.AlignCenter)
        layout.addWidget(self.status_label)

        self.progress_bar = QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setMinimumHeight(26)
        self.progress_bar.setFont(QFont("Microsoft YaHei UI", 10))
        layout.addWidget(self.progress_bar)

        self.log_text = QTextEdit()
        self.log_text.setReadOnly(True)
        self.log_text.setFont(QFont("Microsoft YaHei UI", 10))
        self.log_text.setMinimumHeight(160)
        layout.addWidget(self.log_text)

        btn_layout = QHBoxLayout()
        self.next_btn = QPushButton("下一步")
        self.next_btn.setFont(QFont("Microsoft YaHei UI", 11, QFont.Bold))
        self.next_btn.setMinimumHeight(38)
        self.next_btn.setEnabled(False)
        self.next_btn.clicked.connect(self.on_next_clicked)
        btn_layout.addWidget(self.next_btn)

        self.cancel_btn = QPushButton("取消校准")
        self.cancel_btn.setFont(QFont("Microsoft YaHei UI", 11, QFont.Bold))
        self.cancel_btn.setMinimumHeight(38)
        self.cancel_btn.clicked.connect(self.close)
        btn_layout.addWidget(self.cancel_btn)
        
        layout.addLayout(btn_layout)
        
        self.setLayout(layout)
        
        self.current_step = 0
        self.is_canceled = False
        self.step_completed = False
        self.step1_success = False
        self.step3_retry_count = 0
        self.step6_retry_count = 0
        
        self.torque_k = 0.0
        self.motor_i_kp = 0.0
        self.motor_i_ki = 0.0
        self.motor_i_kd = 0.0
        self.magnetism_value = 0
        
        self.log(f"开始{motor_name}一键校准")
        self.log(f"目标电机ID: {self.motor_id}")
        self.log("=" * 40)
        self.run_next_step()
    
    def log(self, text):
        self.log_text.append(f"[{time.strftime('%H:%M:%S')}] {text}")
        self.log_text.verticalScrollBar().setValue(self.log_text.verticalScrollBar().maximum())
    
    def run_next_step(self):
        if self.is_canceled:
            return
        
        self.step_completed = False
        self.next_btn.setEnabled(False)
        self.next_btn.setText("下一步")
        
        steps = [
            self.step1_motor_id_check,
            self.step2_encoder_x_calibration,
            self.step3_encoder_zero,
            self.step4_foc_calibration,
            self.step5_motor_run_check,
            self.step6_encoder_check,
            self.step7_finish
        ]

        if self.current_step < len(steps):
            # 跳过第二编码器检查（角度验证）
            if steps[self.current_step] == self.step6_encoder_check and not self.angle_check_enabled:
                self.log("角度验证已关闭，跳过步骤六")
                self.current_step += 1
                self.run_next_step()
                return
            self.progress_bar.setValue(int((self.current_step + 1) / len(steps) * 100))
            self.log(f"\n【步骤 {self.current_step + 1}/{len(steps)}】")
            steps[self.current_step]()
        else:
            self.close()
    
    def on_next_clicked(self):
        if not self.is_canceled and self.step_completed:
            self.current_step += 1
            self.run_next_step()
    
    def enable_next_button(self):
        if self.is_canceled:
            return
        self.step_completed = True
        if self.auto_mode:
            QTimer.singleShot(500, self.on_next_clicked)
        else:
            self.next_btn.setEnabled(True)
            self.next_btn.setText("进入下一步")
    
    def step1_motor_id_check(self):
        self.status_label.setText("步骤一：电机ID设置")
        self.step1_success = False
        self.log("正在设置电机ID...")
        self.parent.motor_id_set_callback(self.motor_id)
        self.parent.motor_id_ist_edit.setText(str(self.motor_id))

        self.check_step1_timer = QTimer()
        self.check_step1_timer.timeout.connect(self.check_motor_id)
        self.check_step1_timer.start(500)
        QTimer.singleShot(1000, self.step1_timeout_handler)
    
    def check_motor_id(self):
        current_id = int(self.parent.motor_id_data_ist_edit.text().strip())
        if current_id == self.motor_id:
            self.check_step1_timer.stop()
            self.step1_success = True
            self.log(f"步骤一：电机ID设置成功，当前ID: {current_id}")
            self.enable_next_button()
    
    def step1_timeout_handler(self):
        if self.step1_success:
            return
        if not self.is_canceled:
            self.check_step1_timer.stop()
            self.log("错误：0.5秒内未检测到电机ID，检查线路连接")
            QMessageBox.warning(self, "校准失败", "电机ID检测失败，请检查线路连接！")
            self.close()
    
    def send_read_command(self):
        self.log("发送读取电流参数指令...")
        self.parent.on_motor_i_param_read()
        self.log("等待0.2秒...")
        QTimer.singleShot(200, self.check_current_params)
    
    def check_current_params(self):
        if self.is_canceled:
            return
        try:
            read_torque_k = float(self.parent.torque_k_set_ist_edit.text().strip())
            read_kp = float(self.parent.motor_i_kp_set_ist_edit.text().strip())
            read_ki = float(self.parent.motor_i_ki_set_ist_edit.text().strip())
            read_kd = float(self.parent.motor_i_kd_set_ist_edit.text().strip())
            
            self.log(f"读取到扭矩系数: {read_torque_k}, KP: {read_kp}, KI: {read_ki}, KD: {read_kd}")
            
            torque_k_ok = abs(read_torque_k - self.torque_k) < 0.001
            kp_ok = abs(read_kp - self.motor_i_kp) < 0.001
            ki_ok = abs(read_ki - self.motor_i_ki) < 0.001
            kd_ok = abs(read_kd - self.motor_i_kd) < 0.001
            
            if torque_k_ok and kp_ok and ki_ok and kd_ok:
                self.log("电流参数写入成功")
                self.enable_next_button()
            else:
                error_msg = "电流参数写入失败："
                if not torque_k_ok:
                    error_msg += f"扭矩系数不一致(期望:{self.torque_k},实际:{read_torque_k}); "
                if not kp_ok:
                    error_msg += f"KP不一致(期望:{self.motor_i_kp},实际:{read_kp}); "
                if not ki_ok:
                    error_msg += f"KI不一致(期望:{self.motor_i_ki},实际:{read_ki}); "
                if not kd_ok:
                    error_msg += f"KD不一致(期望:{self.motor_i_kd},实际:{read_kd}); "
                self.log(error_msg)
                QMessageBox.warning(self, "校准失败", error_msg)
                self.close()
        except Exception as e:
            self.log(f"错误：验证电流参数失败 - {str(e)}")
            QMessageBox.warning(self, "校准失败", "验证电流参数失败！")
            self.close()
    
    def step2_encoder_x_calibration(self):
        self.status_label.setText("步骤二：第二编码器X校准")
        self.log("读取磁值输入框...")
        
        try:
            self.magnetism_value = int(self.parent.magnetism_set_edit.text().strip())
            self.log(f"磁值: {self.magnetism_value}")
            self.log("执行第二编码器X校准...")
            
            self.parent.magnetism_callback(1002, self.magnetism_value)
            
            QTimer.singleShot(200, self.step2_complete)
            
        except Exception as e:
            self.log(f"错误：编码器校准失败 - {str(e)}")
            QMessageBox.warning(self, "校准失败", "编码器校准失败！")
            self.close()
    
    def step2_complete(self):
        if self.is_canceled:
            return
        self.log("步骤二：第二编码器X校准完成")
        self.enable_next_button()
    
    def step3_encoder_zero(self):
        self.status_label.setText("步骤三：第二编码器置零")
        self.log("执行第二编码器置零...")
        
        self.parent.motor_joint_ang_zero_callback()
        
        self.step3_check_timer = QTimer()
        self.step3_check_timer.timeout.connect(self.check_angle)
        self.step3_check_timer.start(2000)
    
    def check_angle(self):
        if self.is_canceled:
            return
        try:
            angle_rad = float(self.parent.motor_angle_rad_data_ist_edit.text().strip())
            angle_deg = math.degrees(angle_rad)
            self.log(f"当前角度: {angle_rad:.4f} rad ({angle_deg:.2f}°)")
            if abs(angle_rad) <= 0.0175:  # ±1度 ≈ ±0.0175 rad
                self.step3_check_timer.stop()
                self.log("角度值在±1度范围内")
                self.log("步骤三：第二编码器置零成功")
                self.enable_next_button()
            else:
                self.log(f"角度值: {angle_rad:.4f} rad，超出范围")
                self.step3_check_timer.stop()
                if self.step3_retry_count < 1:
                    self.step3_retry_count += 1
                    self.log(f"角度超出±1度范围，重试第{self.step3_retry_count}次...")
                    self.parent.motor_joint_ang_zero_callback()
                    self.step3_check_timer.start(2000)
                else:
                    self.log("错误：角度超出±1度范围")
                    QMessageBox.warning(self, "校准失败", f"角度值 {angle_deg}° 超出±1度范围！")
                    self.close()
        except:
            pass
    
    def step4_foc_calibration(self):
        self.status_label.setText("步骤四：FOC校准")
        self.log("执行FOC校准...")
        
        self.parent.foc_calibration_callback()
        
        self.log("等待15秒后开始检测扭矩波动...")
        QTimer.singleShot(15000, self.start_foc_timer)
    
    def start_foc_timer(self):
        if self.is_canceled:
            return
        self.log("开始检测扭矩波动...")
        self.foc_check_start_time = time.time()
        self.torque_values = []
        self.foc_check_timer = QTimer()
        self.foc_check_timer.timeout.connect(self.check_torque_fluctuation)
        self.foc_check_timer.start(200)
    
    def check_torque_fluctuation(self):
        if self.is_canceled:
            return
        try:
            torque = float(self.parent.motor_torque_data_ist_edit.text().strip())
            self.torque_values.append(torque)
            
            elapsed = time.time() - self.foc_check_start_time
            
            if elapsed >= 5.0:
                self.foc_check_timer.stop()
                
                if len(self.torque_values) >= 10:
                    max_t = max(self.torque_values)
                    min_t = min(self.torque_values)
                    fluctuation = max_t - min_t
                    
                    if fluctuation > 0.01:
                        self.log(f"步骤四：扭矩波动: {fluctuation:.3f} N·m，校准成功")
                        self.enable_next_button()
                    else:
                        self.log(f"步骤四：扭矩波动: {fluctuation:.3f} N·m，未达到预期")
                        QMessageBox.warning(self, "校准失败", "FOC校准失败，扭矩未波动！")
                        self.close()
                else:
                    QMessageBox.warning(self, "校准失败", "FOC校准数据不足！")
                    self.close()
        except:
            pass
    
    def step5_motor_run_check(self):
        self.status_label.setText("步骤五：电机运行检测")
        self.log("发送正扭矩 1 N·m...")
        
        # 保存原有的控制参数
        self._saved_control_enable = self.parent.motor_control_enable
        self._saved_sin_enable = self.parent.sin_control_enable
        self._saved_torque = self.parent.torque_set_value
        self._saved_Kp_set_value = self.parent.motor_Kp_set_value

        # 发送正扭矩
        self.parent.sin_control_enable = 0
        self.parent.motor_control_enable = 1
        self.parent.torque_set_value = 1.0
        self.parent.motor_Kp_set_value = 10.0


        self.log("等待3秒后记录正转转速...")
        QTimer.singleShot(3000, self.step5_record_positive)
    
    def step5_record_positive(self):
        if self.is_canceled:
            return
        try:
            speed_rad = float(self.parent.motor_speed_rad_data_ist_edit.text().strip())
            self.step5_positive_rpm = abs(speed_rad) * 60 / (2 * math.pi)
            self.log(f"正转转速: {self.step5_positive_rpm:.1f} rpm")
        except:
            self.log("错误：读取正转转速失败")
            QMessageBox.warning(self, "校准失败", "读取电机转速失败！")
            self.parent.motor_control_enable = 0
            self.close()
            return
        
        # 发送负扭矩
        self.log("发送负扭矩 -1 N·m...")
        self.parent.torque_set_value = -1.0
        
        self.log("等待3秒后记录反转转速...")
        QTimer.singleShot(3000, self.step5_record_negative)
    
    def step5_record_negative(self):
        if self.is_canceled:
            return
        try:
            speed_rad = float(self.parent.motor_speed_rad_data_ist_edit.text().strip())
            self.step5_negative_rpm = abs(speed_rad) * 60 / (2 * math.pi)
            self.log(f"反转转速: {self.step5_negative_rpm:.1f} rpm")
        except:
            self.log("错误：读取反转转速失败")
            QMessageBox.warning(self, "校准失败", "读取电机转速失败！")
            self.parent.motor_control_enable = 0
            self.close()
            return
        
        # 停止电机控制
        self.parent.motor_control_enable = 0
        
        # 判断正反转绝对转速差异
        rpm_diff = abs(self.step5_positive_rpm) - abs(self.step5_negative_rpm)
        self.log(f"正反转转速差: {rpm_diff:.1f} rpm")
        
        if abs(rpm_diff) <= 10.0 and abs(self.step5_positive_rpm) > 150.0 and abs(self.step5_negative_rpm) > 150.0:
            self.log("步骤五：电机运行检测通过，等待2秒确保电机停止...")
            QTimer.singleShot(2000, self.enable_next_button)
        else:
            self.log(f"步骤五：电机运行检测失败，转速差 {rpm_diff:.1f} rpm > 10 rpm or 正转转速 {abs(self.step5_positive_rpm):.1f} rpm or 反转转速 {abs(self.step5_negative_rpm):.1f} rpm")
            QMessageBox.warning(self, "校准失败", "电机校准失败，请重新校准！")
            self.close()
    
    def step6_encoder_check(self):
        self.status_label.setText("步骤六：第二编码器检查")

        self.log("发送第二编码器观测指令...")
        self.parent.motor_control_enable = 1004

        if not self.skip_confirm_enabled:
            install_msg = QMessageBox(self)
            install_msg.setWindowTitle("安装确认")
            install_msg.setText("请安装输出盘（不要断电！！！）\n安装完成后点击\"是\"继续校准。")
            install_msg.setFont(QFont("Microsoft YaHei UI", 11, QFont.Bold))
            install_msg.setIcon(QMessageBox.Question)
            install_msg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
            install_msg.setDefaultButton(QMessageBox.No)
            for btn in install_msg.buttons():
                btn.setFont(QFont("Microsoft YaHei UI", 10))
                btn.setMinimumSize(100, 36)
            install_msg.resize(500, 200)
            reply = install_msg.exec_()

            if reply != QMessageBox.Yes:
                self.log("用户取消安装确认，校准终止")
                self.parent.motor_control_enable = 0
                self.close()
                return
        else:
            self.log("跳过安装确认，直接开始检测")

        self.log("开始检测第二编码器...")
        self.step6_angle_values = []
        self.step6_sample_count = 0
        QTimer.singleShot(200, self.step6_read_angle)

    def step6_read_angle(self):
        if self.is_canceled:
            return
        try:
            angle = float(self.parent.motor_torque_data_ist_edit.text().strip())
            self.step6_angle_values.append(angle)
            self.step6_sample_count += 1
            self.log(f"  第{self.step6_sample_count}次读取角度值: {angle:.6f} rad")

            if self.step6_sample_count < 5:
                QTimer.singleShot(200, self.step6_read_angle)
            else:
                self.step6_check_result()
        except:
            self.log("错误：读取角度值失败")
            QMessageBox.warning(self, "校准失败", "读取角度值失败！")
            self.parent.motor_control_enable = 0
            self.close()

    def step6_check_result(self):
        if self.is_canceled:
            return
        self.parent.motor_control_enable = 0

        angle_max = max(self.step6_angle_values)
        angle_min = min(self.step6_angle_values)
        fluctuation = angle_max - angle_min
        self.log(f"角度波动范围: {angle_min:.5f} ~ {angle_max:.5f} rad, 波动: {fluctuation:.3f}")

        if fluctuation < 0.001:
            self.log("步骤六：第二编码器未检测到波动，可能未安装或已损坏")
            QMessageBox.warning(self, "校准失败", "第二编码器可能未安装或已损坏！")
            self.close()
        elif fluctuation <= 0.1:
            self.log("步骤六：第二编码器校准成功")
            self.enable_next_button()
        else:
            self.log(f"步骤六：第二编码器校准失败，角度波动 {fluctuation:.3f} > 0.1")
            if self.step6_retry_count < 3:
                self.step6_retry_count += 1
                self.log(f"角度波动过大，重试第{self.step6_retry_count}次...")
                # self.current_step -= 1
                self.run_next_step()
            else:
                QMessageBox.warning(self, "校准失败", "第二编码器校准失败！")
                self.close()

    def step7_finish(self):
        if self.is_canceled:
            return
        self.status_label.setText("步骤七：校准完成")
        self.progress_bar.setValue(100)
        # 停止电机控制
        self.parent.motor_control_enable = 0
        self.log(f"{self.motor_name}一键校准完成！")
        QMessageBox.information(self, "校准完成", f"{self.motor_name}一键校准完成！")
        QTimer.singleShot(500, self.close)
    
    def closeEvent(self, event):
        self.is_canceled = True
        # 停止电机控制
        self.parent.on_motor_stop_control()
        # 停止所有可能正在运行的定时器
        timers = [
            getattr(self, 'check_step1_timer', None),
            getattr(self, 'step3_check_timer', None),
            getattr(self, 'foc_check_timer', None),
        ]
        for timer in timers:
            if timer and timer.isActive():
                timer.stop()
        event.accept()

class DataType(Enum):
    """数据类型枚举"""
    UINT8 = 'B'
    UINT16 = 'H'
    UINT32 = 'I'
    INT8 = 'b'
    INT16 = 'h'
    INT32 = 'i'
    FLOAT = 'f'
    DOUBLE = 'd'
    CHAR = 's'  # 需要指定长度

data_type = {
    'B': 'uint8_t',
    'H': 'uint16_t',
    'I': 'uint32_t',
    'b': 'int8_t',
    'h': 'int16_t',
    'i': 'int32_t',
    'f': 'float',
    'd': 'double'
}


class StructField:
    """结构体字段定义"""
    
    def __init__(self, name: str, data_type: DataType, count: int = 1, 
                 description: str = ""):
        """
        初始化结构体字段
        
        Args:
            name: 字段名
            data_type: 数据类型
            count: 数量（用于数组）
            description: 字段描述
        """
        self.name = name
        self.data_type = data_type
        self.count = count
        self.description = description
        
    @property
    def format_char(self) -> str:
        """获取格式字符"""
        if self.data_type == DataType.CHAR:
            return f"{self.count}s"
        elif self.count > 1:
            return f"{self.count}{self.data_type.value}"
        else:
            return self.data_type.value
    
    @property
    def size(self) -> int:
        """计算字段大小（字节）"""
        type_sizes = {
            DataType.UINT8: 1,
            DataType.INT8: 1,
            DataType.UINT16: 2,
            DataType.INT16: 2,
            DataType.UINT32: 4,
            DataType.INT32: 4,
            DataType.FLOAT: 4,
            DataType.DOUBLE: 8,
            DataType.CHAR: self.count
        }
        base_size = type_sizes[self.data_type]
        return base_size * self.count
    
    def validate_value(self, value: Any) -> Any:
        """
        验证并格式化字段值
        
        Returns:
            格式化后的值
        """
        if self.data_type == DataType.CHAR:
            # CHAR类型：字符串转字节
            if isinstance(value, str):
                value_bytes = value.encode('utf-8')
                if len(value_bytes) > self.count:
                    value_bytes = value_bytes[:self.count]
                else:
                    value_bytes = value_bytes.ljust(self.count, b'\x00')
                return value_bytes
            elif isinstance(value, bytes):
                if len(value) > self.count:
                    value = value[:self.count]
                else:
                    value = value.ljust(self.count, b'\x00')
                return value
            else:
                raise ValueError(f"字段 {self.name} 需要字符串或字节数据")
        
        elif self.count > 1:
            # 数组类型
            if not isinstance(value, (list, tuple)):
                raise ValueError(f"字段 {self.name} 需要列表数据，但收到 {type(value)}")
            if len(value) != self.count:
                raise ValueError(f"字段 {self.name} 需要 {self.count} 个元素，但收到 {len(value)} 个")
            return value
        
        else:
            # 单值类型
            return value

class StructDefinition:
    """结构体定义基类"""
    
    def __init__(self, name: str, fields: List[StructField], 
                 start_flag: int, end_flag: int,
                 byteorder: str = '<'):
        """
        初始化结构体定义
        
        Args:
            name: 结构体名称
            fields: 字段列表
            start_flag: 起始标志
            end_flag: 结束标志
            byteorder: 字节序 '<'小端 '>'大端 '='原生
        """
        self.name = name
        self.fields = fields
        self.start_flag = start_flag
        self.end_flag = end_flag
        self.byteorder = byteorder
        
        # 构建格式字符串
        self.format_string = byteorder
        self.field_map = {}

        # 添加起始标志
        self.format_string += 'I'
        
        # 添加所有字段
        for field in self.fields:
            self.format_string += field.format_char
            self.field_map[field.name] = field
            
        # 添加结束标志
        self.format_string += 'I'

        # 计算数据部分大小
        self.data_size = sum(f.size for f in self.fields)

        # 计算数据包总大小
        self.packet_size = struct.calcsize(self.format_string)

        # 标志位字节表示（用于搜索）
        self.start_flag_bytes = struct.pack(f'{byteorder}I', start_flag)
        self.end_flag_bytes = struct.pack(f'{byteorder}I', end_flag)
        
    @property
    def size(self) -> int:
        """计算结构体总大小"""
        return self.packet_size
    
    def find_packet_in_buffer(self, buffer: bytes) -> Tuple[Optional[int], Optional[int]]:
        """
        在缓冲区中查找完整的数据包
        
        Args:
            buffer: 字节缓冲区
            
        Returns:
            (起始位置, 结束位置) 或 (None, None)
        """
        buffer_len = len(buffer)
        if buffer_len < self.packet_size:
            return None, None

        # 搜索起始标志
        for i in range(buffer_len - self.packet_size + 1):
            # 检查起始标志
            if buffer[i:i+4] == self.start_flag_bytes:
                # 计算结束标志的位置
                end_flag_pos = i + 4 + self.data_size

                # 确保有足够的数据
                if end_flag_pos + 4 <= buffer_len:
                    # 检查结束标志
                    if buffer[end_flag_pos:end_flag_pos+4] == self.end_flag_bytes:
                        # 找到完整的数据包
                        start_pos = i
                        end_pos = end_flag_pos + 4
                        return start_pos, end_pos
                            
        return None, None
    
    def pack(self, data_dict: Dict[str, Any]) -> bytes:
        """
        打包数据为字节流
        
        Args:
            data_dict: 字段数据字典
            
        Returns:
            打包后的字节流
        """
        # 准备数据列表
        data_list = []
        
        # 添加起始标志
        data_list.append(self.start_flag)
        
        # 添加所有字段数据
        for field in self.fields:
            value = data_dict.get(field.name)
            if value is None:
                raise ValueError(f"字段 {field.name} 缺少数据")
            
            # 验证并格式化值
            formatted_value = field.validate_value(value)
            
            if field.data_type == DataType.CHAR:
                # CHAR类型已经是字节，直接添加
                data_list.append(formatted_value)
            elif field.count > 1:
                # 数组类型：展开为多个参数
                data_list.extend(formatted_value)
            else:
                # 单值类型
                data_list.append(formatted_value)
        
        # 添加结束标志
        data_list.append(self.end_flag)
        
        # 打包数据
        try:
            return struct.pack(self.format_string, *data_list)
        except struct.error as e:
            raise ValueError(f"数据打包失败: {e}")
    
    def unpack(self, data_bytes: bytes) -> Dict[str, Any]:
        """
        解包字节流为数据字典
        
        Args:
            data_bytes: 字节流数据
            
        Returns:
            解包后的数据字典
        """
        if len(data_bytes) != self.packet_size:
            raise ValueError(f"数据长度不匹配: 期望{self.packet_size}字节, 实际{len(data_bytes)}字节")
        
        try:
            unpacked_data = struct.unpack(self.format_string, data_bytes)
        except struct.error as e:
            raise ValueError(f"数据解包失败: {e}")
        
        # 转换为字典
        result = {}
        idx = 0
        
        # 检查起始标志
        start_flag = unpacked_data[idx]
        if start_flag != self.start_flag:
            raise ValueError(f"起始标志错误: 期望0x{self.start_flag:08X}, 实际0x{start_flag:08X}")
        idx += 1
        
        # 提取字段数据
        for field in self.fields:
            if field.data_type == DataType.CHAR:
                value = unpacked_data[idx]
                idx += 1
                # 字节转字符串
                if isinstance(value, bytes):
                    value = value.decode('utf-8').rstrip('\x00')
                    
            elif field.count > 1:
                value = list(unpacked_data[idx:idx + field.count])
                idx += field.count
            else:
                value = unpacked_data[idx]
                idx += 1
            
            result[field.name] = value
        
        # 检查结束标志
        end_flag = unpacked_data[idx]
        if end_flag != self.end_flag:
            raise ValueError(f"结束标志错误: 期望0x{self.end_flag:08X}, 实际0x{end_flag:08X}")
        
        return result
    
    def print_format_info(self):
        """打印格式信息"""
        print(f"结构体: {self.name}")
        print(f"总大小: {self.packet_size} 字节")
        print(f"字节序: {self.byteorder}")
        print(f"格式字符串: {self.format_string}")
        print(f"起始标志: 0x{self.start_flag:08X}")
        print(f"结束标志: 0x{self.end_flag:08X}")
        
        print(f"\n数据部分 ({self.data_size} 字节):")
        for i, field in enumerate(self.fields):
            print(f"  [{i}] {field.name}: {field.data_type.name} x{field.count} "
                  f"({field.size}字节) - {field.description}")
    
    def create_default_data(self) -> Dict[str, Any]:
        """创建默认数据"""
        data = {}
        for field in self.fields:
            # 设置默认值
            if field.data_type == DataType.CHAR:
                data[field.name] = ""
            elif field.count > 1:
                data[field.name] = [0] * field.count
            elif field.data_type in [DataType.FLOAT, DataType.DOUBLE]:
                data[field.name] = 0.0
            else:
                data[field.name] = 0
        return data


class SendStruct(StructDefinition):
    """发送结构体定义"""
    pass


class ReceiveStruct(StructDefinition):
    """接收结构体定义"""
    pass


class SerialStructParser:
    """串口数据解析器"""
    
    def __init__(self, receive_structs: List[ReceiveStruct], buffer_size: int = 4096):
        """
        初始化解析器
        
        Args:
            receive_structs: 接收结构体定义列表（可支持多种格式）
            buffer_size: 缓冲区大小
        """
        self.receive_structs = receive_structs
        self.buffer = bytearray()
        self.buffer_size = buffer_size
        self.packets_received = 0
        self.bytes_processed = 0
        self.packets_dropped = 0
        self.stats_by_type = {struct.name: 0 for struct in receive_structs}
        
    def feed_data(self, data: bytes) -> List[Tuple[str, Dict[str, Any]]]:
        """
        喂入数据，返回解析出的数据包列表
        
        Args:
            data: 接收到的字节数据
            
        Returns:
            解析出的数据包列表 [(结构体名称, 数据字典), ...]
        """
        packets = []

        # 添加到缓冲区
        self.buffer.extend(data)
        self.bytes_processed += len(data)
        
        # 如果缓冲区太大，进行清理
        if len(self.buffer) > self.buffer_size:
            # 尝试查找最近的一个完整包
            found_packet = False
            for struct in self.receive_structs:
                start_pos, _ = struct.find_packet_in_buffer(self.buffer)
                if start_pos is not None and start_pos > 0:
                    # 保留从找到的包开始的数据
                    self.buffer = self.buffer[start_pos:]
                    found_packet = True
                    self.packets_dropped += 1
                    break
            
            if not found_packet:
                # 清空缓冲区
                self.buffer.clear()
        
        # 循环查找数据包
        while True:
            found = False
            
            for struct in self.receive_structs:
                start_pos, end_pos = struct.find_packet_in_buffer(self.buffer)
                if start_pos is not None and end_pos is not None:
                    try:
                        # 提取数据包
                        packet_data = bytes(self.buffer[start_pos:end_pos])
                        
                        # 解析数据包
                        unpacked = struct.unpack(packet_data)
                        packets.append((struct.name, unpacked))
                        
                        # 移除已处理的数据
                        self.buffer = self.buffer[end_pos:]
                        self.packets_received += 1
                        self.stats_by_type[struct.name] += 1
                        found = True
                        break
                        
                    except Exception as e:
                        # 解析失败，跳过这个包
                        print(f"数据包解析失败 ({struct.name}): {e}")
                        # 跳过这个包，从下一个字节开始重新搜索
                        self.buffer = self.buffer[start_pos+1:]
                        found = True
                        break
            
            if not found:
                break
        
        return packets
    
    def clear_buffer(self):
        """清空缓冲区"""
        self.buffer.clear()
        
    def get_stats(self) -> Dict[str, Any]:
        """获取统计信息"""
        stats = {
            "buffer_size": len(self.buffer),
            "packets_received": self.packets_received,
            "bytes_processed": self.bytes_processed,
            "packets_dropped": self.packets_dropped,
        }
        
        # 添加按类型的统计
        for struct_name, count in self.stats_by_type.items():
            stats[f"packets_{struct_name}"] = count
            
        return stats


class SerialStructHandler:
    """串口结构体处理器（支持多种发送和接收结构体）"""
    
    def __init__(self, port: str, baudrate: int = 115200, 
                 timeout: float = 1.0, write_timeout: float = 0.1,
                 buffer_size: int = 4096):
        """
        初始化串口处理器
        
        Args:
            port: 串口号
            baudrate: 波特率
            timeout: 超时时间
            write_timeout: 写入超时时间，防止串口写阻塞GUI线程
            buffer_size: 缓冲区大小
        """
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.write_timeout = write_timeout
        self.buffer_size = buffer_size
        self.serial_port = None
        self.parser = None
        
        # 发送和接收结构体管理
        self.send_structs = {}  # name -> struct
        self.receive_structs = []  # 接收结构体列表
        self.default_send_struct = None  # 默认发送结构体
        
        # 状态
        self.is_connected = False
        self.receive_callback = None
        self.receive_thread = None
        self.running = False
        self.last_error = ""
        
        # 统计
        self.send_stats = defaultdict(int)
        self.receive_stats = defaultdict(int)

    def _mark_connection_lost(self, message: str):
        self.last_error = message
        self.is_connected = False
        self.running = False
        
    def connect(self) -> bool:
        """连接串口"""
        try:
            self.last_error = ""
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout,
                write_timeout=self.write_timeout
            )
            self.is_connected = True
            print(f"串口 {self.port} 连接成功")
            return True
        except Exception as e:
            self.last_error = str(e)
            self.serial_port = None
            self.is_connected = False
            print(f"串口连接失败: {self.last_error}")
            return False
    
    def disconnect(self):
        """断开串口连接"""
        self.stop_receiving()
        serial_port = self.serial_port
        was_connected = self.is_connected or bool(
            serial_port and getattr(serial_port, 'is_open', False)
        )
        try:
            if serial_port and getattr(serial_port, 'is_open', True):
                serial_port.close()
        except Exception as e:
            self.last_error = f"关闭串口失败: {e}"
            print(self.last_error)
        finally:
            self.is_connected = False
            self.serial_port = None
        if was_connected:
            print(f"串口 {self.port} 已断开")
    
    def add_send_struct(self, struct: SendStruct, is_default: bool = False):
        """
        添加发送结构体
        
        Args:
            struct: 发送结构体
            is_default: 是否设为默认发送结构体
        """
        self.send_structs[struct.name] = struct
        print(f"添加发送结构体: {struct.name}")
        
        if is_default or len(self.send_structs) == 1:
            self.default_send_struct = struct
            print(f"  设置为默认发送结构体")
    
    def add_receive_struct(self, struct: ReceiveStruct):
        """添加接收结构体定义"""
        self.receive_structs.append(struct)
        print(f"添加接收结构体: {struct.name}")
        
    def set_receive_structs(self, receive_structs: List[ReceiveStruct]):
        """设置接收结构体定义列表"""
        self.receive_structs = receive_structs
        print(f"设置 {len(receive_structs)} 个接收结构体")
    
    def send_data(self, struct_name: Optional[str] = None, **data) -> bool:
        """
        发送数据（使用指定的发送结构体）
        
        Args:
            struct_name: 结构体名称，为None时使用默认结构体
            **data: 要发送的数据
            
        Returns:
            发送是否成功
        """
        if not self.is_connected or not self.serial_port:
            print("串口未连接")
            return False
        
        # 确定使用哪个结构体
        if struct_name is None:
            if self.default_send_struct is None:
                print("未设置默认发送结构体")
                return False
            struct = self.default_send_struct
        else:
            struct = self.send_structs.get(struct_name)
            if struct is None:
                print(f"未找到发送结构体: {struct_name}")
                return False
        
        try:
            # 打包数据
            packet = struct.pack(data)
            
            # 发送数据
            self.serial_port.write(packet)
            
            # 更新统计
            self.send_stats[struct.name] += 1
            self.send_stats["total_bytes"] += len(packet)
            
            # print(f"发送 {struct.name}: {len(packet)} 字节")
            return True
            
        except (serial.SerialException, OSError) as e:
            self._mark_connection_lost(f"发送数据失败 ({struct.name}): {e}")
            print(self.last_error)
            return False
        except Exception as e:
            print(f"发送数据失败 ({struct.name}): {e}")
            return False
    
    def send_custom(self, struct: SendStruct, data: Dict[str, Any]) -> bool:
        """
        使用自定义结构体发送数据
        
        Args:
            struct: 发送结构体
            data: 要发送的数据
            
        Returns:
            发送是否成功
        """
        if not self.is_connected or not self.serial_port:
            print("串口未连接")
            return False
        
        try:
            # 打包数据
            packet = struct.pack(data)
            
            # 发送数据
            self.serial_port.write(packet)
            
            # 更新统计
            self.send_stats[struct.name] += 1
            self.send_stats["total_bytes"] += len(packet)
            
            print(f"发送 {struct.name}: {len(packet)} 字节")
            return True
            
        except (serial.SerialException, OSError) as e:
            self._mark_connection_lost(f"发送数据失败 ({struct.name}): {e}")
            print(self.last_error)
            return False
        except Exception as e:
            print(f"发送数据失败 ({struct.name}): {e}")
            return False
    
    def receive_data(self, timeout: Optional[float] = None) -> Optional[Tuple[str, Dict[str, Any]]]:
        """
        接收数据（阻塞方式）
        
        Args:
            timeout: 超时时间
            
        Returns:
            (结构体名称, 数据字典) 或 None
        """
        if not self.is_connected or not self.serial_port:
            print("串口未连接")
            return None
        
        if not self.receive_structs:
            print("未设置接收结构体")
            return None
        
        original_timeout = self.serial_port.timeout
        if timeout is not None:
            self.serial_port.timeout = timeout
        
        try:
            # 创建临时解析器
            parser = SerialStructParser(self.receive_structs)
            
            end_time = time.time() + timeout if timeout else float('inf')
            
            while time.time() < end_time:
                # 读取数据
                data = self.serial_port.read(1024)
                if not data:
                    continue
                
                # 喂入解析器
                packets = parser.feed_data(data)
                if packets:
                    struct_name, packet_data = packets[0]
                    self.receive_stats[struct_name] += 1
                    return struct_name, packet_data
            
            return None
            
        except Exception as e:
            print(f"接收数据失败: {e}")
            return None
        finally:
            if timeout is not None:
                self.serial_port.timeout = original_timeout
    
    def start_receiving(self, callback: Callable[[str, Dict[str, Any]], None], 
                        interval: float = 0.01):
        """
        开始异步接收数据
        
        Args:
            callback: 接收到数据时的回调函数 (结构体名称, 数据字典)
            interval: 接收间隔
        """
        if not self.is_connected:
            print("串口未连接")
            return False
            
        if not self.receive_structs:
            print("未设置接收结构体")
            return False

        if self.receive_thread and self.receive_thread.is_alive():
            print("串口接收线程已经运行")
            return True

        # 创建解析器
        self.parser = SerialStructParser(self.receive_structs, self.buffer_size)
        self.receive_callback = callback
        self.running = True
        self.receive_thread = threading.Thread(
            target=self._receive_loop,
            args=(interval,),
            daemon=True
        )
        self.receive_thread.start()
        print("开始异步接收数据")
        return True
    
    def _receive_loop(self, interval: float):
        """接收数据循环"""
        
        while self.running:
            try:
                if self.serial_port.in_waiting > 0:
                    # 读取所有可用数据
                    data = self.serial_port.read(self.serial_port.in_waiting)
                    
                    if data and self.parser:
                        # 解析数据
                        packets = self.parser.feed_data(data)
                        
                        # 调用回调函数
                        for struct_name, packet_data in packets:
                            
                            # 更新统计
                            self.receive_stats[struct_name] += 1
                            
                            if self.receive_callback:
                                self.receive_callback(struct_name, packet_data)
                
                time.sleep(interval)
                
            except (serial.SerialException, OSError) as e:
                self._mark_connection_lost(f"接收循环错误: {e}")
                print(self.last_error)
                break
            except Exception as e:
                print(f"接收循环错误: {e}")
                time.sleep(1)  # 出错后等待1秒
    
    def _print_stats(self):
        """打印统计信息"""
        if self.parser:
            parser_stats = self.parser.get_stats()
            
            print("\n" + "=" * 60)
            print("通信统计信息:")
            print(f"  缓冲区大小: {parser_stats['buffer_size']} 字节")
            print(f"  接收总包数: {parser_stats['packets_received']}")
            
            # 发送统计
            if self.send_stats:
                print(f"\n  发送统计:")
                total_packets = sum(v for k, v in self.send_stats.items() 
                                  if k != "total_bytes")
                print(f"    总包数: {total_packets}")
                print(f"    总字节: {self.send_stats.get('total_bytes', 0)}")
                for name, struct in self.send_structs.items():
                    count = self.send_stats.get(name, 0)
                    if count > 0:
                        print(f"    {name}: {count} 包")
            
            # 接收统计
            if self.receive_stats:
                print(f"\n  接收统计:")
                total_received = sum(self.receive_stats.values())
                print(f"    总包数: {total_received}")
                for struct in self.receive_structs:
                    count = self.receive_stats.get(struct.name, 0)
                    if count > 0:
                        print(f"    {struct.name}: {count} 包")
            print("=" * 60)
    
    def stop_receiving(self):
        """停止异步接收"""
        self.running = False
        receive_thread = self.receive_thread
        if receive_thread and receive_thread is not threading.current_thread():
            receive_thread.join(timeout=1.5)
            if receive_thread.is_alive():
                print("警告：串口接收线程未在超时时间内退出")
        self.receive_thread = None
        
        # 打印最终统计
        if receive_thread or self.parser:
            self._print_stats()
            print("停止异步接收数据")
        self.parser = None
        self.receive_callback = None
        
    def get_send_struct(self, name: str) -> Optional[SendStruct]:
        """获取发送结构体"""
        return self.send_structs.get(name)
    
    def get_all_send_structs(self) -> List[str]:
        """获取所有发送结构体名称"""
        return list(self.send_structs.keys())
    
    def get_all_receive_structs(self) -> List[str]:
        """获取所有接收结构体名称"""
        return [s.name for s in self.receive_structs]


