class SerialDataFifo:
    """有界、线程安全的串口数据 FIFO，支持一次性取出当前批次。"""

    def __init__(self, max_size: int = 20000):
        if max_size <= 0:
            raise ValueError("FIFO容量必须大于0")
        self._max_size = max_size
        self._buffer = deque(maxlen=max_size)
        self._lock = threading.Lock()
        self._written = 0
        self._drained = 0
        self._dropped = 0
        self._max_depth = 0

    def write(self, timestamp: float, struct_name: str, data: Dict[str, Any]) -> None:
        if data is None:
            return

        sample = (timestamp, struct_name, dict(data))
        with self._lock:
            if len(self._buffer) >= self._max_size:
                self._dropped += 1
            self._buffer.append(sample)
            self._written += 1
            self._max_depth = max(self._max_depth, len(self._buffer))

    def drain(self) -> List[Tuple[float, str, Dict[str, Any]]]:
        """原子交换缓冲区；耗时的数据处理在锁外进行。"""
        with self._lock:
            batch = self._buffer
            self._buffer = deque(maxlen=self._max_size)
            self._drained += len(batch)
        return list(batch)

    def clear(self, reset_stats: bool = False) -> None:
        with self._lock:
            self._buffer.clear()
            if reset_stats:
                self._written = 0
                self._drained = 0
                self._dropped = 0
                self._max_depth = 0

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return {
                "written": self._written,
                "drained": self._drained,
                "dropped": self._dropped,
                "depth": len(self._buffer),
                "max_depth": self._max_depth,
            }


